display.text:
 * streamReplyWithRangeFromConsumerPEL() in order to get entries from the
 * consumer pending entries list. However such a function will then call
 * streamReplyWithRange() in order to emit single entries (found in the
 * PEL by ID) to the client. This is the use case for the STREAM_RWR_RAWENTRIES
 * flag.
 */
#define STREAM_RWR_NOACK (1<<0)         /* Do not create entries in the PEL. */
#define STREAM_RWR_RAWENTRIES (1<<1)    /* Do not emit protocol for array
                                           boundaries, just the entries. */
#define STREAM_RWR_HISTORY (1<<2)       /* Only serve consumer local PEL. */
size_t streamReplyWithRange(client *c, stream *s, streamID *start, streamID *end, size_t count, int rev, streamCG *group, streamConsumer *consumer, int flags, streamPropInfo *spi, unsigned long *propCount) {
    void *arraylen_ptr = NULL;
    size_t arraylen = 0;
    streamIterator si;
    int64_t numfields;
    streamID id;
    int propagate_last_id = 0;
    int noack = flags & STREAM_RWR_NOACK;

    if (propCount) *propCount = 0;

    /* If the client is asking for some history, we serve it using a
     * different function, so that we return entries *solely* from its
     * own PEL. This ensures each consumer will always and only see
     * the history of messages delivered to it and not yet confirmed
     * as delivered. */
    if (group && (flags & STREAM_RWR_HISTORY)) {
        return streamReplyWithRangeFromConsumerPEL(c,s,start,end,count,
                                                   consumer);
    }

    if (!(flags & STREAM_RWR_RAWENTRIES))
        arraylen_ptr = addReplyDeferredLen(c);
    streamIteratorStart(&si,s,start,end,rev);

    while(streamIteratorGetID(&si,&id,&numfields)) {
        /* Update the group last_id if needed. */
        if (group && streamCompareID(&id,&group->last_id) > 0) {
            int range_has_tombstones = 0;
            if (!s->length || streamIDEqZero(&s->max_deleted_entry_id)) {
                /* The stream is empty or has no tombstones. */
                range_has_tombstones = 0;
            } else if (streamCompareID(&s->first_id,&s->max_deleted_entry_id) > 0) {
                /* The latest tombstone is before the first entry. */
                range_has_tombstones = 0;
            } else {
                streamID tomb_range_start = id;
                if (tomb_range_start.ms > s->max_deleted_entry_id.ms) {
                    range_has_tombstones = 0;
                } else if (tomb_range_start.ms < s->max_deleted_entry_id.ms) {
                    range_has_tombstones = 1;
                } else {
                    if (tomb_range_start.seq > s->max_deleted_entry_id.seq) {
                        range_has_tombstones = 0;
                    } else {
                        range_has_tombstones = 1;
                    }
                }
            }
            if (group->entries_read != SCG_INVALID_ENTRIES_READ && !range_has_tombstones) {
                /* A valid counter and no future tombstones mean we can
                 * increment the read counter to keep tracking the group's
                 * progress. */
                group->entries_read++;
            } else if (s->entries_added) {
                /* The group's counter may be invalid, so we try to obtain it. */
                group->entries_read = streamEstimateDistanceFromFirstEverEntry(s,&id);
            }
            group->last_id = id;
            /* In the past, we would only set it when NOACK was specified. And in
             * #9127, XCLAIM did not propagate entries_read in ACK, which would
             * cause entries_read to be inconsistent between master and replicas,
             * so here we call streamPropagateGroupID unconditionally. */
            propagate_last_id = 1;
        }

        /* Emit a two elements array for each item. The first is
         * the ID, the second is an array of field-value pairs. */
        addReplyArrayLen(c,2);
        {
            sds idstr = sdsnewlen(SDS_NOINIT, STREAM_ID_STR_LEN);
            sdssetlen(idstr, 0);
            idstr = sdscatfmt(idstr,"%U-%U", id.ms,id.seq);
            addReplyBulkSds(c,idstr);
        }

        addReplyArrayLen(c,numfields*2);

        /* Emit the field-value pairs. */
        while(numfields--) {
            unsigned char *key, *value;
            int64_t key_len, value_len;
            streamIteratorGetField(&si,&key,&value,&key_len,&value_len);
            addReplyBulkCBuffer(c,key,key_len);
            addReplyBulkCBuffer(c,value,value_len);
        }

        /* If a group is passed, we need to create an entry in the
         * PEL (pending entries list) of this group *and* this consumer.
         *
         * Note that we cannot be sure about the fact the message is not
         * already owned by another consumer, because the admin is able
         * to change the consumer group last delivered ID using the
         * XGROUP SETID command. So if we find that there is already
         * a NACK for the entry, we need to associate it to the new
         * consumer. */
        if (group && !noack) {
            unsigned char buf[sizeof(streamID)];
            uint64_t encoded_id[2];
            encoded_id[0] = htonu64(id.ms);
            encoded_id[1] = htonu64(id.seq);
            memcpy(buf,encoded_id,sizeof(encoded_id));

            /* Try to add a new NACK. Most of the time this will work and
             * will not require extra lookups. We'll fix the problem later
             * if we find that there is already a entry for this ID. */
            streamNACK *nack = zmalloc(sizeof(*nack));
            nack->delivery_time = server.cmd_time_snapshot;
            nack->delivery_count = 1;
            nack->consumer = consumer;
            int group_inserted =
                raxTryInsert(group->pel,buf,sizeof(buf),nack,NULL);
            int consumer_inserted =
                raxTryInsert(consumer->pel,buf,sizeof(buf),nack,NULL);

            /* Now we can check if the entry was already busy, and
             * in that case reassign the entry to the new consumer,
             * or update it if the consumer is the same as before. */
            if (group_inserted == 0) {
                streamFreeNACK(nack);
                void *result;
                int found = raxFind(group->pel,buf,sizeof(buf),&result);
                serverAssert(found);
                nack = result;
                raxRemove(nack->consumer->pel,buf,sizeof(buf),NULL);
                /* Update the consumer and NACK metadata. */
                nack->consumer = consumer;
                nack->delivery_time = server.cmd_time_snapshot;
                nack->delivery_count = 1;
                /* Add the entry in the new consumer local PEL. */
                raxInsert(consumer->pel,buf,sizeof(buf),nack,NULL);
            } else if (group_inserted == 1 && consumer_inserted == 0) {
                serverPanic("NACK half-created. Should not be possible.");
            }

            consumer->active_time = server.cmd_time_snapshot;

            /* Propagate as XCLAIM. */
            if (spi) {
                sds idstr = sdsnewlen(SDS_NOINIT, STREAM_ID_STR_LEN);
                sdssetlen(idstr, 0);
                idstr = sdscatfmt(idstr,"%U-%U", id.ms,id.seq);
                robj *idarg = zmalloc(sizeof(*idarg));
                idarg->type = OBJ_STRING;
                idarg->encoding = OBJ_ENCODING_RAW;
                idarg->ptr = idstr;
                idarg->refcount = 1;
                idarg->lru = 0;

                robj *argv[14];
                argv[0] = shared.xclaim;
                argv[1] = spi->keyname;
                argv[2] = spi->groupname;
                size_t consumer_name_len = sdslen(nack->consumer->name);
                if (consumer_name_len <= 44) {
                    robj *consumer_obj = zmalloc(sizeof(robj)+sizeof(struct sdshdr8)+consumer_name_len+1);
                    struct sdshdr8 *sh = (void*)(consumer_obj+1);
                    consumer_obj->type = OBJ_STRING;
                    consumer_obj->encoding = OBJ_ENCODING_EMBSTR;
                    consumer_obj->ptr = sh+1;
                    consumer_obj->refcount = 1;
                    consumer_obj->lru = 0;
                    sh->len = consumer_name_len;
                    sh->alloc = consumer_name_len;
                    sh->flags = SDS_TYPE_8;
                    memcpy(sh->buf,nack->consumer->name,consumer_name_len);
                    sh->buf[consumer_name_len] = '\0';
                    argv[3] = consumer_obj;
                } else {
                    robj *consumer_obj = zmalloc(sizeof(*consumer_obj));
                    consumer_obj->type = OBJ_STRING;
                    consumer_obj->encoding = OBJ_ENCODING_RAW;
                    consumer_obj->ptr = sdsnewlen(nack->consumer->name,consumer_name_len);
                    consumer_obj->refcount = 1;
                    consumer_obj->lru = 0;
                    argv[3] = consumer_obj;
                }
                argv[4] = shared.integers[0];
                argv[5] = idarg;
                argv[6] = shared.time;
                argv[7] = createStringObjectFromLongLong(nack->delivery_time);
                argv[8] = shared.retrycount;
                argv[9] = createStringObjectFromLongLong(nack->delivery_count);
                argv[10] = shared.force;
                argv[11] = shared.justid;
                argv[12] = shared.lastid;
                {
                    sds lastidstr = sdsnewlen(SDS_NOINIT, STREAM_ID_STR_LEN);
                    sdssetlen(lastidstr, 0);
                    lastidstr = sdscatfmt(lastidstr,"%U-%U", group->last_id.ms,group->last_id.seq);
                    robj *lastidobj = zmalloc(sizeof(*lastidobj));
                    lastidobj->type = OBJ_STRING;
                    lastidobj->encoding = OBJ_ENCODING_RAW;
                    lastidobj->ptr = lastidstr;
                    lastidobj->refcount = 1;
                    lastidobj->lru = 0;
                    argv[13] = lastidobj;
                }

                if (!server.replication_allowed || server.loading) {
                    /* Skip extra propagation while loading or when
                     * replication is explicitly disabled. */
                } else {
                    alsoPropagate(c->db->id,argv,14,PROPAGATE_AOF|PROPAGATE_REPL);
                }

                decrRefCount(argv[3]);
                decrRefCount(argv[7]);
                decrRefCount(argv[9]);
                decrRefCount(argv[13]);

